// ─── TOAST ────────────────────────────────────────────────────────────────────
function Toast({msg}){
  return msg ? <div style={{position:"fixed",bottom:90,left:"50%",transform:"translateX(-50%)",background:"#1a1a1a",color:"#fff",borderRadius:24,padding:"10px 22px",fontSize:13,fontWeight:600,zIndex:9999,whiteSpace:"nowrap",boxShadow:"0 4px 20px rgba(0,0,0,0.3)"}}>{msg}</div> : null;
}

