      {/* Subtle gold glow */}
      <div style={{position:"absolute",top:"30%",left:"50%",transform:"translate(-50%,-50%)",width:300,height:300,background:"radial-gradient(circle,rgba(201,168,76,0.25) 0%,transparent 70%)",borderRadius:"50%"}}/>
